}

// GenMac generates a random MAC address for a given OUI.
func GenMac(oui string) (net.HardwareAddr, error) {
	buf := make([]byte, 3)
	_, _ = rand.Read(buf)

	hwa, err := net.ParseMAC(fmt.Sprintf("%s:%02x:%02x:%02x", oui, buf[0], buf[1], buf[2]))
	return hwa, err
