func CreateOrGetNamedNetNS(name string) (string, error) {
	if nsPath, err := GetNamedNetNS(name); err == nil {
		return nsPath, nil
	}

	return CreateNamedNetNS(name)
}

func GetNamedNetNS(name string) (string, error) {
	nsPath := filepath.Join("/run/netns", name)
	if !FileOrDirExists(nsPath) {
		return "", fmt.Errorf("named netns %q does not exist", name)
	}

	return nsPath, nil
}

// SanitizeInterfaceName sanitizes the interface name by replacing '/' and ' ' with '-'.
// Making it suitable to write as AltName for the interface.
func SanitizeInterfaceName(ifaceName string) string {
	var sb strings.Builder
	sb.Grow(len(ifaceName))

	for _, char := range ifaceName {
		switch char {
		case '/', ' ':
			sb.WriteRune('-')
		default:
			sb.WriteRune(char)
		}
	}

	return sb.String()
}

